1	package com.eaglepoint.storefront.domain.usecase
2	
3	import com.eaglepoint.storefront.domain.model.UserRole
4	import com.eaglepoint.storefront.security.SessionManager
5	
6	class RoleGuard(private val sessionManager: SessionManager) {
7	
8	    fun canAccessIngestionLogs(role: UserRole): Boolean {
9	        return role in setOf(UserRole.ADMIN, UserRole.EDITOR, UserRole.ANALYST)
10	    }
11	
12	    fun canCurateContent(role: UserRole): Boolean {
13	        return role in setOf(UserRole.ADMIN, UserRole.EDITOR)
14	    }
15	
16	    fun canConfigureSourceRules(role: UserRole): Boolean {
17	        return role == UserRole.ADMIN
18	    }
19	
20	    fun canAccessCartData(role: UserRole): Boolean {
21	        return role in setOf(UserRole.ADMIN, UserRole.USER)
22	    }
23	
24	    fun canAccessAuditLogs(role: UserRole): Boolean {
25	        return role in setOf(UserRole.ADMIN, UserRole.EDITOR, UserRole.ANALYST)
26	    }
27	
28	    fun canManageUsers(role: UserRole): Boolean {
29	        return role == UserRole.ADMIN
30	    }
31	
32	    fun canPerformBackupRestore(role: UserRole): Boolean {
33	        return role == UserRole.ADMIN
34	    }
35	
36	    fun canExportAuditLogs(role: UserRole): Boolean {
37	        return role == UserRole.ADMIN
38	    }
39	
40	    fun requireRole(actual: UserRole, required: Set<UserRole>) {
41	        if (actual !in required) {
42	            throw SecurityException("Access denied: role '$actual' not in $required")
43	        }
44	    }
45	
46	    fun enforceSourceRuleAccess() {
47	        val role = sessionManager.requireRole()
48	        if (!canConfigureSourceRules(role)) {
49	            throw SecurityException("Access denied: source rule management requires ADMIN role")
50	        }
51	    }
52	
53	    fun enforceIngestionConsoleAccess() {
54	        val role = sessionManager.requireRole()
55	        if (!canAccessIngestionLogs(role)) {
56	            throw SecurityException("Access denied: ingestion console requires ADMIN, EDITOR, or ANALYST role")
57	        }
58	    }
59	
60	    fun enforceAuditLogAccess() {
61	        val role = sessionManager.requireRole()
62	        if (!canAccessAuditLogs(role)) {
63	            throw SecurityException("Access denied: audit log requires ADMIN, EDITOR, or ANALYST role")
64	        }
65	    }
66	
67	    fun enforceAuditExportAccess() {
68	        val role = sessionManager.requireRole()
69	        if (!canExportAuditLogs(role)) {
70	            throw SecurityException("Access denied: audit export requires ADMIN role")
71	        }
72	    }
73	
74	    fun enforceCurationAccess() {
75	        val role = sessionManager.requireRole()
76	        if (!canCurateContent(role)) {
77	            throw SecurityException("Access denied: content curation requires ADMIN or EDITOR role")
78	        }
79	    }
80	
81	    fun enforceBackupRestoreAccess() {
82	        val role = sessionManager.requireRole()
83	        if (!canPerformBackupRestore(role)) {
84	            throw SecurityException("Access denied: backup/restore requires ADMIN role")
85	        }
86	    }
87	
88	    fun enforceCartOwnership(cartUserId: String?) {
89	        sessionManager.requireOwnership(cartUserId)
90	    }
91	}
