1	package com.eaglepoint.storefront.domain.usecase
2	
3	import com.eaglepoint.storefront.data.repository.ArticleRepository
4	import com.eaglepoint.storefront.domain.model.AuditAction
5	import com.eaglepoint.storefront.domain.model.CurationStatus
6	import com.eaglepoint.storefront.domain.model.UserRole
7	
8	class CurateArticleUseCase(
9	    private val articleRepository: ArticleRepository,
10	    private val roleGuard: RoleGuard,
11	    private val logAuditEvent: LogAuditEventUseCase
12	) {
13	
14	    suspend fun approve(articleId: String, userId: String, userRole: UserRole): Result<Unit> {
15	        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
16	        return try {
17	            articleRepository.updateCurationStatus(articleId, CurationStatus.APPROVED, userId)
18	            logAuditEvent(userId, AuditAction.ARTICLE_APPROVED, "article", articleId)
19	            Result.success(Unit)
20	        } catch (e: Exception) {
21	            Result.failure(e)
22	        }
23	    }
24	
25	    suspend fun reject(articleId: String, userId: String, userRole: UserRole, reason: String? = null): Result<Unit> {
26	        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
27	        return try {
28	            articleRepository.updateCurationStatus(articleId, CurationStatus.REJECTED, userId)
29	            logAuditEvent(userId, AuditAction.ARTICLE_REJECTED, "article", articleId, reason)
30	            Result.success(Unit)
31	        } catch (e: Exception) {
32	            Result.failure(e)
33	        }
34	    }
35	
36	    suspend fun setFeatured(articleId: String, featured: Boolean, userId: String, userRole: UserRole): Result<Unit> {
37	        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
38	        return try {
39	            articleRepository.setFeatured(articleId, featured)
40	            if (featured) {
41	                articleRepository.updateCurationStatus(articleId, CurationStatus.FEATURED, userId)
42	            }
43	            logAuditEvent(
44	                userId,
45	                if (featured) AuditAction.ARTICLE_FEATURED else AuditAction.ARTICLE_UNFEATURED,
46	                "article", articleId
47	            )
48	            Result.success(Unit)
49	        } catch (e: Exception) {
50	            Result.failure(e)
51	        }
52	    }
53	
54	    suspend fun updateTags(
55	        articleId: String, team: String?, league: String?, topic: String?,
56	        userId: String, userRole: UserRole
57	    ): Result<Unit> {
58	        roleGuard.requireRole(userRole, setOf(UserRole.ADMIN, UserRole.EDITOR))
59	        return try {
60	            articleRepository.updateTags(articleId, team, league, topic)
61	            logAuditEvent(
62	                userId, AuditAction.ARTICLE_TAGS_UPDATED, "article", articleId,
63	                "team=$team, league=$league, topic=$topic"
64	            )
65	            Result.success(Unit)
66	        } catch (e: Exception) {
67	            Result.failure(e)
68	        }
69	    }
70	}
