2	
3	import com.eaglepoint.storefront.data.db.dao.AuditEventDao
4	import com.eaglepoint.storefront.data.db.entity.AuditEventEntity
5	import com.eaglepoint.storefront.domain.model.AuditAction
6	import com.eaglepoint.storefront.domain.model.AuditEvent
7	import com.eaglepoint.storefront.security.SensitiveFieldMasker
8	import kotlinx.coroutines.CoroutineDispatcher
9	import kotlinx.coroutines.Dispatchers
10	import kotlinx.coroutines.flow.Flow
11	import kotlinx.coroutines.flow.map
12	import kotlinx.coroutines.withContext
13	
14	class AuditRepository(
15	    private val auditEventDao: AuditEventDao,
16	    private val dispatcher: CoroutineDispatcher = Dispatchers.IO
17	) {
18	
19	    suspend fun log(event: AuditEvent) = withContext(dispatcher) {
20	        val maskedDetail = event.detail?.let { detail ->
21	            if (SensitiveFieldMasker.isSensitive("detail")) "****" else detail
22	        }
23	        val entity = AuditEventEntity(
24	            id = event.id,
25	            userId = event.userId,
26	            action = event.action.name,
27	            target = event.target,
28	            targetId = event.targetId?.let { SensitiveFieldMasker.maskId(it) },
29	            timestamp = event.timestamp,
30	            detail = maskedDetail
31	        )
32	        auditEventDao.insert(entity)
33	    }
34	
35	    fun getPage(limit: Int, offset: Int): Flow<List<AuditEvent>> {
36	        return auditEventDao.getPage(limit, offset).map { entities ->
37	            entities.map { entityToDomain(it) }
38	        }
39	    }
40	
41	    fun getByAction(action: AuditAction): Flow<List<AuditEvent>> {
42	        return auditEventDao.getByAction(action.name).map { entities ->
43	            entities.map { entityToDomain(it) }
44	        }
45	    }
46	
47	    fun getByDateRange(from: Long, to: Long): Flow<List<AuditEvent>> {
48	        return auditEventDao.getByDateRange(from, to).map { entities ->
49	            entities.map { entityToDomain(it) }
50	        }
51	    }
52	
53	    suspend fun count(): Int = withContext(dispatcher) {
54	        auditEventDao.count()
55	    }
56	
57	    private fun entityToDomain(entity: AuditEventEntity): AuditEvent {
58	        return AuditEvent(
59	            id = entity.id,
60	            userId = entity.userId,
61	            action = AuditAction.valueOf(entity.action),
62	            target = entity.target,
63	            targetId = entity.targetId,
64	            timestamp = entity.timestamp,
65	            detail = entity.detail
66	        )
67	    }
68	}
