1	package com.eaglepoint.storefront.domain.usecase
2	
3	import com.eaglepoint.storefront.data.repository.SourceRuleRepository
4	import com.eaglepoint.storefront.domain.model.IngestionJobRun
5	import com.eaglepoint.storefront.ingestion.IngestionEngine
6	
7	class RunIngestionUseCase(
8	    private val ingestionEngine: IngestionEngine,
9	    private val sourceRuleRepository: SourceRuleRepository
10	) {
11	
12	    suspend fun runAll(userId: String): List<IngestionJobRun> {
13	        return ingestionEngine.runIngestionForAllSources(userId)
14	    }
15	
16	    suspend fun runForSource(sourceRuleId: String, userId: String): Result<IngestionJobRun> {
17	        val rule = sourceRuleRepository.findById(sourceRuleId)
18	            ?: return Result.failure(IllegalArgumentException("Source rule not found: $sourceRuleId"))
19	
20	        if (!rule.isActive) {
21	            return Result.failure(IllegalStateException("Source rule is not active: ${rule.name}"))
22	        }
23	
24	        return try {
25	            val result = ingestionEngine.runIngestionForSource(rule, userId)
26	            Result.success(result)
27	        } catch (e: Exception) {
28	            Result.failure(e)
29	        }
30	    }
31	}
