19	) : CoroutineWorker(appContext, workerParams), KoinComponent {
20	
21	    private val ingestionEngine: IngestionEngine by inject()
22	
23	    override suspend fun doWork(): Result {
24	        return try {
25	            val results = ingestionEngine.runIngestionForAllSources(SYSTEM_USER_ID)
26	            val allSucceeded = results.all {
27	                it.status == com.eaglepoint.storefront.domain.model.IngestionStatus.SUCCESS
28	            }
29	
30	            if (allSucceeded || results.isEmpty()) {
31	                Result.success()
32	            } else {
33	                val failures = results.count {
34	                    it.status == com.eaglepoint.storefront.domain.model.IngestionStatus.FAILURE
35	                }
36	                if (failures == results.size) {
37	                    // All failed — retry with backoff
38	                    if (runAttemptCount < MAX_RETRY_COUNT) {
39	                        Result.retry()
40	                    } else {
41	                        Result.failure()
42	                    }
43	                } else {
44	                    // Partial success
45	                    Result.success()
46	                }
47	            }
48	        } catch (e: Exception) {
49	            if (runAttemptCount < MAX_RETRY_COUNT) {
50	                Result.retry()
51	            } else {
52	                Result.failure()
53	            }
54	        }
55	    }
56	
57	    companion object {
58	        const val WORK_NAME = "ingestion_periodic"
59	        const val SYSTEM_USER_ID = "system"
60	        const val MAX_RETRY_COUNT = 3
61	        private const val DEFAULT_INTERVAL_HOURS = 6L
62	        private const val BACKOFF_DELAY_MINUTES = 5L
63	
64	        fun schedule(
65	            context: Context,
66	            intervalHours: Long = DEFAULT_INTERVAL_HOURS,
67	            replaceExisting: Boolean = false
68	        ) {
69	            val constraints = Constraints.Builder()
70	                .setRequiresCharging(true)
71	                .setRequiresDeviceIdle(true)
72	                .setRequiredNetworkType(NetworkType.CONNECTED)
73	                .build()
74	
75	            val workRequest = PeriodicWorkRequestBuilder<IngestionWorker>(
76	                intervalHours, TimeUnit.HOURS
77	            )
78	                .setConstraints(constraints)
79	                .setBackoffCriteria(
80	                    BackoffPolicy.EXPONENTIAL,
81	                    BACKOFF_DELAY_MINUTES,
82	                    TimeUnit.MINUTES
83	                )
84	                .build()
85	
86	            val policy = if (replaceExisting) {
87	                ExistingPeriodicWorkPolicy.UPDATE
88	            } else {
89	                ExistingPeriodicWorkPolicy.KEEP
90	            }
91	
92	            WorkManager.getInstance(context)
93	                .enqueueUniquePeriodicWork(WORK_NAME, policy, workRequest)
94	        }
95	
96	        fun cancel(context: Context) {
97	            WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME)
98	        }
99	    }
100	}
